pragma solidity 0.8.14;

import {PoolBridgeable} from './PoolBridgeable.sol';
import {PoolWithFeeCalculatorERC20} from './PoolWithFeeCalculatorERC20.sol';

/// @notice Biochar pool contract
contract Biochar is PoolWithFeeCalculatorERC20, PoolBridgeable {
    // ----------------------------------------
    //      Constants
    // ----------------------------------------

    /// @dev Version-related parameters. VERSION keeps track of production
    /// releases. VERSION_RELEASE_CANDIDATE keeps track of iterations
    /// of a VERSION in our staging environment.
    string public constant VERSION = '1.1.0';
    uint256 public constant VERSION_RELEASE_CANDIDATE = 1;

    // ----------------------------------------
    //      Upgradable related functions
    // ----------------------------------------

    function initialize(address[] calldata accounts, bytes32[] calldata roles)
        external
        virtual
        initializer
    {
        __Pool_init_unchained(accounts, roles);
        __ERC20_init_unchained('Biochar', 'CHAR');
    }

    /// @dev Exposed for backwards compatibility and will be removed
    /// in a future version. Use totalProjectSupply instead.
    function totalPerProjectTCO2Supply(uint256 projectTokenId)
        external
        view
        returns (uint256)
    {
        return totalProjectSupply[projectTokenId];
    }

    /// @dev Exposed for backwards compatibility and will be removed
    /// in a future version. Use tokenBalance instead.
    function tokenBalances(address tco2) public view returns (uint256) {
        return tokenBalance(tco2);
    }

    /// @dev Exposed for backwards compatibility and will be removed
    /// in a future version. Use totalUnderlyingSupply instead.
    function totalTCO2Supply() external view returns (uint256) {
        return totalUnderlyingSupply;
    }
}

contracts/pools/Pool.sol.content:
// SPDX-FileCopyrightText: 2021 Toucan Labs
//
// SPDX-License-Identifier: UNLICENSED

// If you encounter a vulnerability or an issue, please contact <security@toucan.earth> or visit security.toucan.earth
pragma solidity 0.8.14;

import '@openzeppelin/contracts-upgradeable/token/ERC20/ERC20Upgradeable.sol';
import '@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol';
import '@openzeppelin/contracts-upgradeable/utils/ContextUpgradeable.sol';
import '@openzeppelin/contracts-upgradeable/security/PausableUpgradeable.sol';
import '@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol';
import {FeeDistribution, IFeeCalculator} from '@toucanprotocol/dynamic-fee-pools/src/interfaces/IFeeCalculator.sol';

import '../bases/RoleInitializer.sol';
import '../interfaces/IToucanCarbonOffsets.sol';
import {Errors} from '../libraries/Errors.sol';
import './interfaces/IPoolFilter.sol';
import './PoolStorage.sol';

/// @notice Pool template contract
/// ERC20 compliant token that acts as a pool for vintage tokens
abstract contract Pool is
    ContextUpgradeable,
    ERC20Upgradeable,
    OwnableUpgradeable,
    PausableUpgradeable,
    RoleInitializer,
    UUPSUpgradeable,
    PoolStorage
{
    // ----------------------------------------
    //      Constants
    // ----------------------------------------

    /// @dev All roles related to accessing this contract
    bytes32 public constant PAUSER_ROLE = keccak256('PAUSER_ROLE');
    bytes32 public constant MANAGER_ROLE = keccak256('MANAGER_ROLE');

    /// @dev divider to calculate fees in basis points
    uint256 public constant feeRedeemDivider = 1e4;

    // ----------------------------------------
    //      Events
    // ----------------------------------------

    event DepositFeePaid(address depositor, uint256 fees);
    event RedeemFeePaid(address redeemer, uint256 fees);
    event RedeemFeeBurnt(address redeemer, uint256 fees);
    event RedeemBurnFeeUpdated(uint256 feeBp);
    event RedeemFeeBurnAddressUpdated(address receiver);
    event RedeemFeeExempted(address exemptedUser, bool isExempted);
    event SupplyCapUpdated(uint256 newCap);
    event FilterUpdated(address filter);
    event AddFeeExemptedTCO2(address tco2);
    event RemoveFeeExemptedTCO2(address tco2);
    event MinimumTCLSeedingThresholdUpdated(uint256 newThreshold);

    struct PoolVintageToken {
        // Address of the token contract. This can be either
        // an ERC-20 or an ERC-1155 token.
        address tokenAddress;
        // Token id for ERC-1155 tokens. For ERC-20 tokens,
        // this field should always be 0.
        uint256 erc1155VintageTokenId;
        // Token id to identify uniquely a project for a vintage
        // token in the pool. This id should be derived from the
        // combination of tokenAddress and erc1155VintageTokenId,
        // depending on the token type of the vintage.
        uint256 projectTokenId;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function __Pool_init_unchained(
        address[] calldata accounts,
        bytes32[] calldata roles
    ) internal {
        __Context_init_unchained();
        __Ownable_init_unchained();
        __Pausable_init_unchained();
        __UUPSUpgradeable_init_unchained();
        __RoleInitializer_init_unchained(accounts, roles);
    }

    // ----------------------------------------
    //                Abstract
    // ----------------------------------------

    function _feeDistribution(PoolVintageToken memory vintage, uint256)
        internal
        view
        virtual
        returns (FeeDistribution memory);

    function _transfer(
        PoolVintageToken memory vintage,
        address from,
        address to,
        uint256 amount
    ) internal virtual;

    function _retire(
        PoolVintageToken memory vintage,
        address from,
        uint256 amount
    ) internal virtual returns (uint256);

    function _checkEligible(PoolVintageToken memory vintage)
        internal
        view
        virtual;

    function _emitDepositedEvent(
        PoolVintageToken memory vintage,
        uint256 amount
    ) internal virtual;

    function _emitRedeemedEvent(PoolVintageToken memory vintage, uint256 amount)
        internal
        virtual;

    // ----------------------------------------
    //      Upgradable related functions
    // ----------------------------------------

    function _authorizeUpgrade(address) internal virtual override {
        onlyPoolOwner();
    }

    // ------------------------
    // Poor person's modifiers
    // ------------------------

    /// @dev function that checks whether the caller is the
    /// contract owner
    function onlyPoolOwner() internal view {
        require(owner() == msg.sender, Errors.CP_ONLY_OWNER);
    }

    /// @dev function that only lets the contract's owner and granted role to execute
    function onlyWithRole(bytes32 role) internal view {
        require(
            hasRole(role, msg.sender) || owner() == msg.sender,
            Errors.CP_UNAUTHORIZED
        );
    }

    /// @dev function that checks whether the contract is paused
    function onlyUnpaused() internal view {
        require(!paused(), Errors.CP_PAUSED_CONTRACT);
    }

    // ------------------------
    // Admin functions
    // ------------------------

    /// @notice Emergency function to disable contract's core functionality
    /// @dev wraps _pause(), only Admin
    function pause() external {
        onlyWithRole(PAUSER_ROLE);
        _pause();
    }

    /// @dev Unpause the system, wraps _unpause(), only Admin
    function unpause() external {
        onlyWithRole(PAUSER_ROLE);
        _unpause();
    }

    /// @notice Update the fee redeem burn percentage
    /// @param feeRedeemBurnPercentageInBase_ percentage of fee in base
    function setFeeRedeemBurnPercentage(uint256 feeRedeemBurnPercentageInBase_)
        external
        virtual
    {
        onlyPoolOwner();
        require(
            feeRedeemBurnPercentageInBase_ < feeRedeemDivider,
            Errors.CP_INVALID_FEE
        );
        _feeRedeemBurnPercentageInBase = feeRedeemBurnPercentageInBase_;
        emit RedeemBurnFeeUpdated(feeRedeemBurnPercentageInBase_);
    }

    /// @notice Update the fee redeem burn address
    /// @param feeRedeemBurnAddress_ address to transfer the fees to burn
    function setFeeRedeemBurnAddress(address feeRedeemBurnAddress_) external {
        onlyPoolOwner();
        require(feeRedeemBurnAddress_ != address(0), Errors.CP_EMPTY_ADDRESS);
        _feeRedeemBurnAddress = feeRedeemBurnAddress_;
        emit RedeemFeeBurnAddressUpdated(feeRedeemBurnAddress_);
    }

    /// @notice Adds a new address for redeem fees exemption
    /// @param _address address to be exempted on redeem fees
    function addRedeemFeeExemptedAddress(address _address) external {
        onlyPoolOwner();
        redeemFeeExemptedAddresses[_address] = true;
        emit RedeemFeeExempted(_address, true);
    }

    /// @notice Removes an address from redeem fees exemption
    /// @param _address address to be removed from exemption
    function removeRedeemFeeExemptedAddress(address _address) external {
        onlyPoolOwner();
        redeemFeeExemptedAddresses[_address] = false;
        emit RedeemFeeExempted(_address, false);
    }

    /// @notice Adds a new TCO2 for redeem fees exemption
    /// @param _tco2 TCO2 to be exempted on redeem fees
    function addRedeemFeeExemptedTCO2(address _tco2) external {
        onlyPoolOwner();
        redeemFeeExemptedTCO2s[_tco2] = true;
        emit AddFeeExemptedTCO2(_tco2);
    }

    /// @notice Removes a TCO2 from redeem fees exemption
    /// @param _tco2 TCO2 to be removed from exemption
    function removeRedeemFeeExemptedTCO2(address _tco2) external {
        onlyPoolOwner();
        redeemFeeExemptedTCO2s[_tco2] = false;
        emit RemoveFeeExemptedTCO2(_tco2);
    }

    /// @notice Function to limit the maximum pool supply
    /// @dev supplyCap is initially set to 0 and must be increased before deposits
    /// @param newCap New pool supply cap
    function setSupplyCap(uint256 newCap) external virtual {
        onlyPoolOwner();
        supplyCap = newCap;
        emit SupplyCapUpdated(newCap);
    }

    /// @notice Update the address of the filter contract
    /// @param _filter Filter contract address
    function setFilter(address _filter) external virtual {
        onlyPoolOwner();
        filter = _filter;
        emit FilterUpdated(_filter);
    }

    function setMinimumTCLSeedingThreshold(uint256 _minimumTCLSeedingThreshold)
        external
    {
        onlyWithRole(MANAGER_ROLE);
        minimumTCLSeedingThreshold = _minimumTCLSeedingThreshold;
        emit MinimumTCLSeedingThresholdUpdated(_minimumTCLSeedingThreshold);
    }

    // ----------------------------
    //   Permissionless functions
    // ----------------------------

    function _deposit(
        PoolVintageToken memory vintage,
        uint256 amountE18,
        uint256 maxFee
    ) internal returns (uint256 mintedPoolTokenAmount) {
        onlyUnpaused();

        // Ensure the vintage token is eligible to be deposited
        _checkEligible(vintage);

        // Ensure there is space in the pool
        uint256 remainingSpace = getRemaining();
        //slither-disable-next-line incorrect-equality
        if (remainingSpace == 0) {
            revert(Errors.CP_FULL_POOL);
        }

        // If the amount to be deposited exceeds the remaining space, deposit
        // the maximum amount possible up to the cap instead of failing.
        if (amountE18 > remainingSpace) amountE18 = remainingSpace;

        uint256 depositedAmount = amountE18;
        uint256 feeDistributionTotal = 0;
        if (
            totalUnderlyingSupply + amountE18 >= minimumTCLSeedingThreshold &&
            feeCalculator != IFeeCalculator(address(0))
        ) {
            // we take a fee only on the part of the deposited amount that brings the total over the threshold
            uint256 chargeableAmount = totalUnderlyingSupply >=
                minimumTCLSeedingThreshold
                ? amountE18
                : amountE18 +
                    totalUnderlyingSupply -
                    minimumTCLSeedingThreshold;

            // If a fee module is configured, use it to calculate the minting fees
            FeeDistribution memory feeDistribution = _feeDistribution(
                vintage,
                chargeableAmount
            );
            feeDistributionTotal = getFeeDistributionTotal(feeDistribution);
            _checkMaxFee(maxFee, feeDistributionTotal);
            depositedAmount -= feeDistributionTotal;

            // Distribute the fee between the recipients
            uint256 recipientLen = feeDistribution.recipients.length;
            for (uint256 i = 0; i < recipientLen; ++i) {
                _mint(feeDistribution.recipients[i], feeDistribution.shares[i]);
            }
            emit DepositFeePaid(msg.sender, feeDistributionTotal);
        }

        // Mint pool tokens to the user based on the amount of the deposited
        // underlying token
        mintedPoolTokenAmount = _mint(
            msg.sender,
            depositedAmount,
            feeDistributionTotal,
            vintage
        );

        // Update supply-related storage variables in the pool
        _changeSupply(vintage, int256(amountE18));

        // Transfer the underlying token to the pool
        _transfer(vintage, msg.sender, address(this), amountE18);

        _emitDepositedEvent(vintage, amountE18);
    }

    /// @notice Function to mint pool tokens based on the amount of TCO2
    /// @dev This function enables the minting of pool tokens based on the amount and the vintage token
    /// @dev For generic Pool contract the minting is 1:1
    function _mint(
        address account,
        uint256 amount,
        uint256, /* fee */
        PoolVintageToken memory
    ) internal virtual returns (uint256) {
        super._mint(account, amount);
        return amount;
    }

    /// @notice Function to burn pool tokens based on the amount of TCO2
    /// @dev This function enables the burning of pool tokens based on the amount and the vintage token
    /// @dev For generic Pool contract the burning is 1:1
    function _burn(
        address account,
        uint256 amount,
        PoolVintageToken memory
    ) internal virtual returns (uint256) {
        super._burn(account, amount);
        return amount;
    }

    /// @notice Returns minimum vintage start time for this pool
    function minimumVintageStartTime() external view returns (uint64) {
        return IPoolFilter(filter).minimumVintageStartTime();
    }

    /// @notice Checks if region is eligible for this pool
    function regions(string calldata region) external view returns (bool) {
        return IPoolFilter(filter).regions(region);
    }

    /// @notice Checks if standard is eligible for this pool
    function standards(string calldata standard) external view returns (bool) {
        return IPoolFilter(filter).standards(standard);
    }

    /// @notice Checks if methodology is eligible for this pool
    function methodologies(string calldata methodology)
        external
        view
        returns (bool)
    {
        return IPoolFilter(filter).methodologies(methodology);
    }

    /// @dev Internal function to calculate redemption fees according to the
    /// amounts of pool tokens to be spent
    /// Made virtual so that each child contract can implement its own
    /// internal fee calculation logic that can be shared with the
    /// current Pool contract. Child contracts will most likely need
    /// to simply expose a public function that returns just the
    /// feeDistributionTotal which is the value that is useful to
    /// external clients who only care about the total fee amount and
    /// not how the fee is going to be distributed.
    function _calculateRedemptionInFees(
        PoolVintageToken[] memory vintages,
        uint256[] memory amounts,
        bool toRetire
    )
        internal
        view
        virtual
        returns (
            uint256[] memory feeAmounts,
            FeeDistribution memory feeDistribution
        );

    /// @dev Internal function to calculate redemption fees according to the
    /// amounts of TCO2 to be redeemed
    /// Made virtual so that each child contract can implement its own
    /// internal fee calculation logic that can be shared with the
    /// current Pool contract. Child contracts will most likely need
    /// to simply expose a public function that returns just the
    /// feeDistributionTotal which is the value that is useful to
    /// external clients who only care about the total fee amount and
    /// not how the fee is going to be distributed.
    function _calculateRedemptionOutFees(
        PoolVintageToken[] memory vintages,
        uint256[] memory amounts,
        bool toRetire
    )
        internal
        view
        virtual
        returns (
            uint256 feeDistributionTotal,
            FeeDistribution memory feeDistribution
        );

    function getFeeDistributionTotal(FeeDistribution memory feeDistribution)
        internal
        pure
        returns (uint256 feeAmount)
    {
        uint256 recipientLen = feeDistribution.recipients.length;
        _checkLength(recipientLen, feeDistribution.shares.length);

        for (uint256 i = 0; i < recipientLen; ++i) {
            feeAmount += feeDistribution.shares[i];
        }
        return feeAmount;
    }

    function _redeemInMany(
        PoolVintageToken[] memory vintages,
        uint256[] memory amounts,
        uint256 maxFee,
        bool toRetire
    )
        internal
        returns (
            uint256[] memory retirementIds,
            uint256[] memory redeemedAmounts
        )
    {
        onlyUnpaused();
        uint256 vintageLength = vintages.length;
        _checkLength(vintageLength, amounts.length);
        require(
            feeCalculator == IFeeCalculator(address(0)),
            Errors.CP_NOT_SUPPORTED
        );

        // Initialize return arrays
        redeemedAmounts = new uint256[](vintageLength);
        if (toRetire) {
            retirementIds = new uint256[](vintageLength);
        }

        // Calculate the fees to be paid for the vintage token redemptions
        (
            uint256[] memory feeAmounts,
            FeeDistribution memory feeDistribution
        ) = _calculateRedemptionInFees(vintages, amounts, toRetire);

        // Execute redemptions
        uint256 totalFee = 0;

        for (uint256 i = 0; i < vintageLength; ++i) {
            _checkEligible(vintages[i]);

            uint256 amountToRedeem = amounts[i];
            amountToRedeem -= feeAmounts[i];
            totalFee += feeAmounts[i];

            // Redeem the amount minus the fee
            //slither-disable-next-line unused-return
            _redeemSingle(vintages[i], amountToRedeem);

            // If requested, retire the vintage tokens in one go. Callers should
            // first approve the pool in order for the pool to retire
            // on behalf of them
            if (toRetire) {
                retirementIds[i] = _retire(
                    vintages[i],
                    msg.sender,
                    amountToRedeem
                );
            }

            // Keep track of redeemed amounts in return arguments
            // to make the function composable.
            redeemedAmounts[i] = amountToRedeem;
        }

        _checkMaxFee(maxFee, totalFee);

        // Distribute the fee between the recipients
        if (totalFee > 0) {
            _distributeRedemptionFee(
                feeDistribution.recipients,
                feeDistribution.shares
            );
        }
    }

    function _checkMaxFee(uint256 maxFee, uint256 amount) internal pure {
        if (maxFee != 0) {
            // Protect caller against getting charged a higher fee than expected
            require(amount <= maxFee, Errors.CP_FEE_TOO_HIGH);
        }
    }

    function _changeSupply(PoolVintageToken memory vintage, int256 delta)
        internal
        virtual
    {
        uint256 currentSupply = totalProjectSupply[vintage.projectTokenId];
        totalProjectSupply[vintage.projectTokenId] = uint256(
            int256(currentSupply) + delta
        );
        totalUnderlyingSupply = uint256(int256(totalUnderlyingSupply) + delta);
    }

    function _redeemOutMany(
        PoolVintageToken[] memory vintages,
        uint256[] memory amountsE18,
        uint256 maxFee,
        bool toRetire
    )
        internal
        returns (uint256[] memory retirementIds, uint256 poolAmountSpent)
    {
        onlyUnpaused();
        uint256 vintageLength = vintages.length;
        _checkLength(vintageLength, amountsE18.length);

        // Initialize return arrays
        if (toRetire) {
            retirementIds = new uint256[](vintageLength);
        }

        // Calculate the fee to be paid for the vintage token redemptions
        (
            uint256 feeDistributionTotal,
            FeeDistribution memory feeDistribution
        ) = _calculateRedemptionOutFees(vintages, amountsE18, toRetire);
        _checkMaxFee(maxFee, feeDistributionTotal);
        poolAmountSpent += feeDistributionTotal;

        // Distribute the fee between the recipients
        if (feeDistributionTotal != 0) {
            _distributeRedemptionFee(
                feeDistribution.recipients,
                feeDistribution.shares
            );
        }

        // Execute redemptions
        for (uint256 i = 0; i < vintageLength; ++i) {
            _checkEligible(vintages[i]);

            // Redeem the amount
            uint256 amountToRedeem = amountsE18[i];
            poolAmountSpent += _redeemSingle(vintages[i], amountToRedeem);

            // If requested, retire the vintage tokens in one go. Callers should
            // first approve the pool in order for the pool to retire
            // on behalf of them
            if (toRetire) {
                retirementIds[i] = _retire(
                    vintages[i],
                    msg.sender,
                    amountToRedeem
                );
            }
        }
    }

    // Distribute the fees between the recipients
    function _distributeRedemptionFee(
        address[] memory recipients,
        uint256[] memory fees
    ) internal {
        uint256 amountToBurn = 0;
        for (uint256 i = 0; i < recipients.length; ++i) {
            uint256 fee = fees[i];
            uint256 burnAmount = (fee * _feeRedeemBurnPercentageInBase) /
                feeRedeemDivider;
            fee -= burnAmount;
            amountToBurn += burnAmount;
            transfer(recipients[i], fee);
            emit RedeemFeePaid(msg.sender, fee);
        }
        if (amountToBurn > 0) {
            transfer(_feeRedeemBurnAddress, amountToBurn);
            emit RedeemFeeBurnt(msg.sender, amountToBurn);
        }
    }

    /// @dev Internal function that redeems a single underlying token
    function _redeemSingle(PoolVintageToken memory vintage, uint256 amountE18)
        internal
        virtual
        returns (uint256 burntAmount)
    {
        // Burn pool tokens
        burntAmount = _burn(msg.sender, amountE18, vintage);

        // Update supply-related storage variables in the pool
        _changeSupply(vintage, int256(amountE18) * -1);

        // Transfer vintage token tokens to the caller
        _transfer(vintage, address(this), msg.sender, amountE18);

        _emitRedeemedEvent(vintage, amountE18);
    }

    /// @dev Implemented in order to disable transfers when paused
    function _beforeTokenTransfer(
        address from,
        address to,
        uint256 amount
    ) internal virtual override {
        super._beforeTokenTransfer(from, to, amount);

        onlyUnpaused();
    }

    function _checkLength(uint256 l1, uint256 l2) internal pure {
        if (l1 != l2) {
            revert(Errors.CP_LENGTH_MISMATCH);
        }
    }

    /// @dev Returns the remaining space in pool before hitting the cap
    function getRemaining() public view returns (uint256) {
        return (supplyCap - totalSupply());
    }

    // -----------------------------
    //      Locked ERC20 safety
    // -----------------------------

    /// @dev Function to disallowing sending tokens to either the 0-address
    /// or this contract itself
    function validDestination(address to) internal view {
        require(to != address(0x0), Errors.CP_INVALID_DESTINATION_ZERO);
        require(to != address(this), Errors.CP_INVALID_DESTINATION_SELF);
    }

    function transfer(address recipient, uint256 amount)
        public
        virtual
        override
        returns (bool)
    {
        validDestination(recipient);
        super.transfer(recipient, amount);
        return true;
    }

    function transferFrom(
        address sender,
        address recipient,
        uint256 amount
    ) public virtual override returns (bool) {
        validDestination(recipient);
        super.transferFrom(sender, recipient, amount);
        return true;
    }
}

contracts/pools/PoolBridgeable.sol.content:
// SPDX-FileCopyrightText: 2021 Toucan Labs
//
// SPDX-License-Identifier: UNLICENSED

// If you encounter a vulnerability or an issue, please contact <security@toucan.earth> or visit security.toucan.earth
pragma solidity 0.8.14;

import '../cross-chain/interfaces/IToucanCrosschainMessenger.sol';
import '../interfaces/IToucanCarbonOffsets.sol';
import {Errors} from '../libraries/Errors.sol';
import {Pool} from './Pool.sol';

abstract contract PoolBridgeable is Pool {
    // ----------------------------------------
    //      Events
    // ----------------------------------------

    event RouterUpdated(address router);

    event TCO2RebalanceRequestInitiated(
        uint32 indexed destinationDomain,
        address[] tco2s,
        uint256[] amounts
    );
    event TCO2RebalanceRequestCompleted(address[] tco2s, uint256[] amounts);

    // -------------------------------------
    //   Functions
    // -------------------------------------

    function onlyRouter() internal view {
        require(msg.sender == router, Errors.CP_ONLY_ROUTER);
    }

    /// @notice method to set router address
    /// @dev use this method to set router address
    /// @param _router address of ToucanCrosschainMessenger
    function setRouter(address _router) external {
        onlyPoolOwner();
        // router address can be set to zero to make bridgeMint and bridgeBurn unusable
        router = _router;
        emit RouterUpdated(_router);
    }

    /// @notice mint tokens to receiver account that were cross-chain bridged
    /// @dev invoked only by the ToucanCrosschainMessenger (Router)
    /// @param _account account that will be minted with corss-chain bridged tokens
    /// @param _amount amount of tokens that will be minted
    function bridgeMint(address _account, uint256 _amount) external {
        onlyRouter();
        _mint(_account, _amount);
    }

    /// @notice burn tokens from account to be cross-chain bridged
    /// @dev invoked only by the ToucanCrosschainMessenger (Router)
    /// @param _account account that will be burned with corss-chain bridged tokens
    /// @param _amount amount of tokens that will be burned
    function bridgeBurn(address _account, uint256 _amount) external {
        onlyRouter();
        _burn(_account, _amount);
    }

    function _getRemotePoolAddress(address tcm, uint32 destinationDomain)
        internal
        view
        returns (address recipient)
    {
        RemoteTokenInformation memory remoteInfo = IToucanCrosschainMessenger(
            tcm
        ).remoteTokens(address(this), destinationDomain);
        recipient = remoteInfo.tokenAddress;
        require(recipient != address(0), Errors.CP_EMPTY_ADDRESS);
    }

    /// @notice Get the fee needed to bridge TCO2s into the destination domain.
    /// @param destinationDomain The domain to bridge TCO2s to
    /// @param tco2s The TCO2s to bridge
    /// @param amounts The amounts of TCO2s to bridge
    /// @return fee The fee amount to be paid
    function quoteBridgeTCO2sFee(
        uint32 destinationDomain,
        address[] calldata tco2s,
        uint256[] calldata amounts
    ) external view returns (uint256 fee) {
        uint256 tco2Length = tco2s.length;
        _checkLength(tco2Length, amounts.length);

        address tcm = router;
        address recipient = _getRemotePoolAddress(tcm, destinationDomain);

        fee = IToucanCrosschainMessenger(tcm).quoteBridgeTCO2sFee(
            destinationDomain,
            tco2s,
            amounts,
            recipient
        );
    }

    /// @notice Allows MANAGER or the owner to bridge TCO2s into
    /// another domain.
    /// @param destinationDomain The domain to bridge TCO2s to
    /// @param tco2s The TCO2s to bridge
    /// @param amounts The amounts of TCO2s to bridge
    function bridgeTCO2s(
        uint32 destinationDomain,
        address[] calldata tco2s,
        uint256[] calldata amounts
    ) external payable {
        onlyWithRole(MANAGER_ROLE);
        uint256 tco2Length = tco2s.length;
        require(tco2Length != 0, Errors.CP_EMPTY_ARRAY);
        _checkLength(tco2Length, amounts.length);

        // TODO: Disallow bridging more TCO2s than an amount that
        // would bring the pool to imbalance, ie., end up with more
        // pool tokens than TCO2s in the pool in the source chain.

        // Read the address of the remote pool from ToucanCrosschainMessenger
        // and set that as a recipient in our cross-chain messages.
        address tcm = router;
        address recipient = _getRemotePoolAddress(tcm, destinationDomain);

        //slither-disable-next-line uninitialized-local
        for (uint256 i; i < tco2Length; ++i) {
            address tco2 = tco2s[i];
            uint256 amount = amounts[i];

            // Update supply-related storage variables in the pool
            VintageData memory vData = IToucanCarbonOffsets(tco2)
                .getVintageData();
            require(
                totalProjectSupply[vData.projectTokenId] >= amount,
                'insufficient vintage amount'
            );
            totalProjectSupply[vData.projectTokenId] -= amount;
            // this is enforced by an implicit invariant that makes
            // sure a single project supply can never be more than
            // the total underlying supply. Adding a check will
            // anyway make debugging easier should the invariant
            // unexpectedly be broken.
            require(
                totalUnderlyingSupply >= amount,
                'insufficient underlying supply'
            );
            totalUnderlyingSupply -= amount;
        }

        // Transfer tokens to recipient
        //slither-disable-next-line reentrancy-eth
        IToucanCrosschainMessenger(tcm).bridgeTCO2s{value: msg.value}(
            destinationDomain,
            tco2s,
            amounts,
            recipient
        );

        emit TCO2RebalanceRequestInitiated(destinationDomain, tco2s, amounts);
    }

    /// @notice Allows a router to complete the bridging of tokens.
    /// It transfers the tokens to the pool itself and updates the counters.
    /// @param tco2s The TCO2s that have been bridged
    /// @param amounts The amounts of TCO2s that have been bridged
    function completeTCO2Bridging(
        address[] calldata tco2s,
        uint256[] calldata amounts
    ) external {
        onlyRouter();
        uint256 tco2Length = tco2s.length;
        require(tco2Length != 0, Errors.CP_EMPTY_ARRAY);
        _checkLength(tco2Length, amounts.length);

        //slither-disable-next-line uninitialized-local
        for (uint256 i; i < tco2Length; ++i) {
            address tco2 = tco2s[i];
            uint256 amount = amounts[i];

            // Update supply-related storage variables in the pool
            VintageData memory vData = IToucanCarbonOffsets(tco2)
                .getVintageData();

            PoolVintageToken memory vintage = PoolVintageToken(
                tco2,
                0,
                vData.projectTokenId
            );

            // Update supply-related storage variables in the pool
            _changeSupply(vintage, int256(amount));

            // Transfer the underlying token to the pool
            _transfer(vintage, msg.sender, address(this), amount);
        }

        emit TCO2RebalanceRequestCompleted(tco2s, amounts);
    }
}

contracts/pools/PoolERC20able.sol.content:
// SPDX-FileCopyrightText: 2024 Toucan Labs
//
// SPDX-License-Identifier: UNLICENSED

// If you encounter a vulnerability or an issue, please contact <security@toucan.earth> or visit security.toucan.earth
pragma solidity 0.8.14;

import '@openzeppelin/contracts-upgradeable/token/ERC20/utils/SafeERC20Upgradeable.sol';
import {FeeDistribution} from '@toucanprotocol/dynamic-fee-pools/src/interfaces/IFeeCalculator.sol';

import {VintageData, IToucanCarbonOffsets} from '../interfaces/IToucanCarbonOffsets.sol';
import {Errors} from '../libraries/Errors.sol';
import {IPoolFilter} from './interfaces/IPoolFilter.sol';
import {Pool} from './Pool.sol';

abstract contract PoolERC20able is Pool {
    using SafeERC20Upgradeable for IERC20Upgradeable;

    event Deposited(address erc20Addr, uint256 amount);
    event Redeemed(address account, address erc20, uint256 amount);

    /// @notice Return the total supply of the project for the
    /// given TCO2 token.
    /// @return supply
    function totalPerProjectSupply(address tco2)
        external
        view
        returns (uint256)
    {
        return totalProjectSupply[_projectTokenId(tco2)];
    }

    /// @notice Redeem a whitelisted TCO2 without paying any fees and burn
    /// the TCO2. Initially added to burn HFC-23 credits, can be used in the
    /// future to dispose of any other whitelisted credits.
    /// @dev User needs to approve the pool contract in the TCO2 contract for
    /// the amount to be burnt before executing this function.
    /// @param tco2 TCO2 to redeem and burn
    /// @param amount Amount to redeem and burn
    function redeemAndBurn(address tco2, uint256 amount) external {
        onlyUnpaused();
        require(redeemFeeExemptedTCO2s[tco2], Errors.CP_NOT_EXEMPTED);
        //slither-disable-next-line unused-return
        _redeemSingle(_buildPoolVintageToken(tco2), amount);
        // User has to approve the pool contract in the TCO2 contract
        // in order for this function to successfully burn the tokens
        IToucanCarbonOffsets(tco2).burnFrom(msg.sender, amount);
    }

    /// @notice View function to calculate deposit fees pre-execution
    /// @dev User specifies in front-end the address and amount they want
    /// @param tco2 TCO2 contract addresses
    /// @param amount Amount to deposit
    /// @return feeDistributionTotal Total fee amount to be paid
    function calculateDepositFees(address tco2, uint256 amount)
        external
        view
        virtual
        returns (uint256 feeDistributionTotal);

    /// @notice View function to calculate redemption fees pre-execution,
    /// according to the amounts of pool tokens to be spent.
    /// @param tco2s Array of TCO2 contract addresses
    /// @param amounts Array of pool token amounts to spend in order to redeem TCO2s.
    /// The indexes of this array are matching 1:1 with the tco2s array.
    /// @param toRetire Whether the TCO2s will be retired atomically
    /// with the redemption. It may be that lower fees will be charged
    /// in this case.
    /// @return feeDistributionTotal Total fee amount to be paid
    function calculateRedemptionInFees(
        address[] memory tco2s,
        uint256[] memory amounts,
        bool toRetire
    ) external view virtual returns (uint256 feeDistributionTotal);

    /// @notice View function to calculate redemption fees pre-execution,
    /// according to the amounts of TCO2 to be redeemed.
    /// @param tco2s Array of TCO2 contract addresses
    /// @param amounts Array of TCO2 amounts to redeem.
    /// The indexes of this array are matching 1:1 with the tco2s array.
    /// @param toRetire Whether the TCO2s will be retired atomically
    /// with the redemption. It may be that lower fees will be charged
    /// in this case.
    /// @return feeDistributionTotal Total fee amount to be paid
    function calculateRedemptionOutFees(
        address[] memory tco2s,
        uint256[] memory amounts,
        bool toRetire
    ) external view virtual returns (uint256 feeDistributionTotal);

    /// @notice Returns the balance of the carbon offset found in the pool
    /// @param tco2 TCO2 contract address
    /// @return balance pool balance
    function tokenBalance(address tco2) public view returns (uint256) {
        return IERC20Upgradeable(tco2).balanceOf(address(this));
    }

    /// @notice Checks if token to be deposited is eligible for this pool.
    /// Reverts if not.
    /// Beware that the revert reason might depend on the underlying implementation
    /// of IPoolFilter.checkEligible
    /// @param vintageToken the contract to check
    /// @return isEligible true if address is eligible and no other issues occur
    function checkEligible(address vintageToken)
        external
        view
        virtual
        returns (bool isEligible)
    {
        _checkEligible(_buildPoolVintageToken(vintageToken));
        return true;
    }

    // Internal

    function _emitDepositedEvent(
        PoolVintageToken memory vintage,
        uint256 amount
    ) internal override {
        emit Deposited(vintage.tokenAddress, amount);
    }

    function _emitRedeemedEvent(PoolVintageToken memory vintage, uint256 amount)
        internal
        override
    {
        emit Redeemed(msg.sender, vintage.tokenAddress, amount);
    }

    function _checkEligible(PoolVintageToken memory vintage)
        internal
        view
        override
    {
        //slither-disable-next-line unused-return
        string memory eligibilityError = IPoolFilter(filter).checkEligible(
            vintage.tokenAddress
        );

        if (bytes(eligibilityError).length > 0) {
            revert(eligibilityError);
        }
    }

    function _feeDistribution(PoolVintageToken memory vintage, uint256 amount)
        internal
        view
        virtual
        override
        returns (FeeDistribution memory)
    {
        return
            feeCalculator.calculateDepositFees(
                address(this),
                vintage.tokenAddress,
                amount
            );
    }

    function _transfer(
        PoolVintageToken memory vintage,
        address from,
        address to,
        uint256 amount
    ) internal virtual override {
        if (from == address(this)) {
            IERC20Upgradeable(vintage.tokenAddress).safeTransfer(to, amount);
        } else {
            IERC20Upgradeable(vintage.tokenAddress).safeTransferFrom(
                from,
                to,
                amount
            );
        }
    }

    function _retire(
        PoolVintageToken memory vintage,
        address from,
        uint256 amount
    ) internal override returns (uint256) {
        return
            IToucanCarbonOffsets(vintage.tokenAddress).retireFrom(from, amount);
    }

    function _buildPoolVintageTokens(address[] memory tco2s)
        internal
        view
        returns (PoolVintageToken[] memory vintages)
    {
        uint256 length = tco2s.length;
        vintages = new PoolVintageToken[](length);
        for (uint256 i = 0; i < length; i++) {
            vintages[i] = _buildPoolVintageToken(tco2s[i]);
        }
    }

    function _buildPoolVintageToken(address tco2)
        internal
        view
        returns (PoolVintageToken memory)
    {
        return PoolVintageToken(tco2, 0, _projectTokenId(tco2));
    }

    function _projectTokenId(address tco2) internal view returns (uint256) {
        return IToucanCarbonOffsets(tco2).getVintageData().projectTokenId;
    }
}

contracts/pools/PoolStorage.sol.content:
// SPDX-FileCopyrightText: 2021 Toucan Labs
//
// SPDX-License-Identifier: UNLICENSED

// If you encounter a vulnerability or an issue, please contact <security@toucan.earth> or visit security.toucan.earth
pragma solidity 0.8.14;

import {IFeeCalculator} from '@toucanprotocol/dynamic-fee-pools/src/interfaces/IFeeCalculator.sol';

abstract contract PoolStorageV1 {
    /// @notice The supply cap is used as a measure to guard deposits
    /// in the pool. It is meant to minimize the impact a potential
    /// compromise in the source registry (eg. Verra) can have to the pool.
    uint256 public supplyCap;
    //slither-disable-next-line constable-states
    mapping(address => uint256) private DEPRECATED_tokenBalances;
    //slither-disable-next-line constable-states
    address private DEPRECATED_contractRegistry;

    /// @notice array used to read from when redeeming TCO2s automatically
    address[] public scoredTCO2s;

    /// @dev Mappings for attributes that can be included or excluded
    /// if set to `false`, attribute-values are blacklisted/rejected
    /// if set to `true`, attribute-values are whitelisted/accepted
    //slither-disable-next-line constable-states
    mapping(string => bool) private DEPRECATED_regions;
    //slither-disable-next-line constable-states
    mapping(string => bool) private DEPRECATED_standards;
    //slither-disable-next-line constable-states
    mapping(string => bool) private DEPRECATED_methodologies;

    /// @dev mapping to whitelist external non-TCO2 contracts by address
    //slither-disable-next-line constable-states
    mapping(address => bool) private DEPRECATED_externalWhiteList;

    /// @dev mapping to include certain TCO2 contracts by address,
    /// overriding attribute matching checks
    //slither-disable-next-line constable-states
    mapping(address => bool) private DEPRECATED_internalWhiteList;

    /// @dev mapping to exclude certain TCO2 contracts by address,
    /// even if the attribute matching would pass
    //slither-disable-next-line constable-states
    mapping(address => bool) private DEPRECATED_internalBlackList;

    /// @dev fees redeem receiver address
    //slither-disable-next-line uninitialized-state,constable-states
    address internal _feeRedeemReceiver;

    //slither-disable-next-line uninitialized-state,constable-states
    uint256 internal _feeRedeemPercentageInBase;

    /// @dev fees redeem burn address
    address internal _feeRedeemBurnAddress;

    /// @dev fees redeem burn percentage with 2 fixed decimals precision
    uint256 internal _feeRedeemBurnPercentageInBase;

    /// @dev repacked smaller variables here so new bools can be added below
    //slither-disable-next-line constable-states
    uint64 private DEPRECATED_minimumVintageStartTime;
    //slither-disable-next-line constable-states
    bool private DEPRECATED_seedMode;
    //slither-disable-next-line constable-states
    bool private DEPRECATED_regionsIsAcceptedMapping;
    //slither-disable-next-line constable-states
    bool private DEPRECATED_standardsIsAcceptedMapping;
    //slither-disable-next-line constable-states
    bool private DEPRECATED_methodologiesIsAcceptedMapping;
}

abstract contract PoolStorageV1_1 {
    /// @notice End users exempted from redeem fees
    mapping(address => bool) public redeemFeeExemptedAddresses;
}

abstract contract PoolStorageV1_2 {
    /// @notice TCO2s exempted from redeem fees
    mapping(address => bool) public redeemFeeExemptedTCO2s;
}

abstract contract PoolStorageV1_3 {
    /// @notice bridge router who has access to the bridgeMint & bridgeBurn functions which
    /// mint/burn pool tokens for cross chain messenges
    //slither-disable-next-line constable-states
    address public router;
}

abstract contract PoolStorageV1_4 {
    /// @notice fee percentage in basis points charged for selective
    /// redemptions that also retire the credits in the same transaction
    //slither-disable-next-line uninitialized-state,constable-states
    uint256 internal _feeRedeemRetirePercentageInBase;
    address public filter;
}

abstract contract PoolStorageV1_5 {
    /// @notice module to calculate fees for the pool
    //slither-disable-next-line uninitialized-state,constable-states
    IFeeCalculator public feeCalculator;
    /// @notice Total supply of underlying collateral in the pool.  Supply
    /// amounts are kept in the underlying's native precision regardless
    /// of whether underlying is an ERC-20 or ERC-1155 token.
    uint256 public totalUnderlyingSupply;
    /// @notice Project token id to total supply of the project
    /// in the pool. Supply amounts are kept in the underlying's native
    /// precision regardless of whether underlying is an ERC-20 or ERC-1155
    /// token.
    mapping(uint256 => uint256) public totalProjectSupply;
}

abstract contract PoolStorageV1_6 {
    /// @notice Mapping to track scores for ERC-1155 tokens
    mapping(address => mapping(uint256 => uint256)) internal _scores;

    mapping(address => mapping(uint256 => bool)) internal _vintageDeposited;
    /// @notice Underlying decimals for ERC-1155 tokens. 0 decimals means
    /// that the smallest denomination the ERC-1155 token can represent is
    /// a tonne, 3 decimals means a kilogram, etc.
    //slither-disable-next-line constable-states
    uint8 internal _underlyingDecimals;
}

abstract contract PoolStorageV1_7 {
    uint256 public minimumTCLSeedingThreshold;
}

abstract contract PoolStorage is
    PoolStorageV1,
    PoolStorageV1_1,
    PoolStorageV1_2,
    PoolStorageV1_3,
    PoolStorageV1_4,
    PoolStorageV1_5,
    PoolStorageV1_6,
    PoolStorageV1_7
{}

contracts/pools/PoolWithFeeCalculatorERC.content:
// SPDX-FileCopyrightText: 2024 Toucan Labs
//
// SPDX-License-Identifier: UNLICENSED

// If you encounter a vulnerability or an issue, please contact <security@toucan.earth> or visit security.toucan.earth
pragma solidity 0.8.14;

import {FeeDistribution, IFeeCalculator} from '@toucanprotocol/dynamic-fee-pools/src/interfaces/IFeeCalculator.sol';

import {PoolERC20able} from './PoolERC20able.sol';
import {Errors} from '../libraries/Errors.sol';

/// @notice Pool with fee calculator template contract
/// Any pool that inherits from this contract will be able to
// charge fees both on deposits and redemptions with the use
/// of a fee calculator contract.
abstract contract PoolWithFeeCalculatorERC20 is PoolERC20able {
    // ----------------------------------------
    //      Events
    // ----------------------------------------

    event FeeCalculatorUpdated(address feeCalculator);

    // ------------------------
    // Admin functions
    // ------------------------

    /// @notice Update the address of the fee module contract
    /// @param _feeCalculator Fee module contract address
    function setFeeCalculator(address _feeCalculator) external {
        onlyPoolOwner();
        feeCalculator = IFeeCalculator(_feeCalculator);
        emit FeeCalculatorUpdated(_feeCalculator);
    }

    // ----------------------------
    //   Permissionless functions
    // ----------------------------

    /// @notice View function to calculate deposit fees pre-execution
    /// @dev User specifies in front-end the address and amount they want
    /// @param tco2 TCO2 contract address
    /// @param amount Amount to redeem
    /// @return feeDistributionTotal Total fee amount to be paid
    function calculateDepositFees(address tco2, uint256 amount)
        external
        view
        override
        returns (uint256 feeDistributionTotal)
    {
        onlyUnpaused();

        // If the fee calculator is not configured or the amount doesn't bring us to the threshold, no fees are paid
        if (
            totalUnderlyingSupply + amount < minimumTCLSeedingThreshold ||
            address(feeCalculator) == address(0)
        ) {
            return 0;
        }

        uint256 chargeableAmount = totalUnderlyingSupply >=
            minimumTCLSeedingThreshold
            ? amount
            : amount + totalUnderlyingSupply - minimumTCLSeedingThreshold;
        FeeDistribution memory feeDistribution = feeCalculator
            .calculateDepositFees(address(this), tco2, chargeableAmount);
        feeDistributionTotal = getFeeDistributionTotal(feeDistribution);
    }

    /// @notice View function to calculate fees pre-execution,
    /// according to the amounts of pool tokens to be spent.
    /// NOTE: This function is not supported yet
    function calculateRedemptionInFees(
        address[] memory, /* tco2s */
        uint256[] memory, /* amounts */
        bool /* toRetire */
    )
        external
        pure
        override
        returns (
            uint256 /* feeDistribution */
        )
    {
        revert(Errors.CP_NOT_SUPPORTED);
    }

    function _calculateRedemptionInFees(
        PoolVintageToken[] memory, /* tco2s */
        uint256[] memory, /* amounts */
        bool /* toRetire */
    )
        internal
        pure
        override
        returns (
            uint256[] memory, /* feeAmounts */
            FeeDistribution memory /* feeDistribution */
        )
    {
        revert(Errors.CP_NOT_SUPPORTED);
    }

    /// @notice View function to calculate fees pre-execution,
    /// according to the amounts of TCO2 to be redeemed.
    /// @param tco2s Array of TCO2 contract addresses
    /// @param amounts Array of TCO2 amounts to redeem
    /// The indexes of this array are matching 1:1 with the tco2s array.
    /// @param toRetire Whether the TCO2s will be retired atomically
    /// with the redemption. It may be that lower fees will be charged
    /// in this case. Currently not supported.
    /// @return feeDistributionTotal Total fee amount to be paid
    function calculateRedemptionOutFees(
        address[] memory tco2s,
        uint256[] memory amounts,
        bool toRetire
    ) external view override returns (uint256 feeDistributionTotal) {
        PoolVintageToken[] memory vintages = _buildPoolVintageTokens(tco2s);
        (feeDistributionTotal, ) = _calculateRedemptionOutFees(
            vintages,
            amounts,
            toRetire
        );
    }

    function _calculateRedemptionOutFees(
        PoolVintageToken[] memory vintages,
        uint256[] memory amounts,
        bool toRetire
    )
        internal
        view
        override
        returns (
            uint256 feeDistributionTotal,
            FeeDistribution memory feeDistribution
        )
    {
        onlyUnpaused();
        // Calculating fees for retiring is not supported yet
        require(!toRetire, Errors.CP_NOT_SUPPORTED);
        // Calculating fees for multi-TCO2 redemptions is not supported yet
        uint256 vintageLength = vintages.length;
        require(vintageLength == 1, Errors.CP_NOT_SUPPORTED);
        _checkLength(vintageLength, amounts.length);

        // If the fee calculator is not configured or the caller is exempted, no fees are paid
        if (
            address(feeCalculator) == address(0) ||
            redeemFeeExemptedAddresses[msg.sender]
        ) {
            return (0, FeeDistribution(new address[](0), new uint256[](0)));
        }

        address[] memory tco2s = new address[](vintageLength);
        for (uint256 i = 0; i < vintageLength; i++) {
            tco2s[i] = vintages[i].tokenAddress;
        }

        feeDistribution = feeCalculator.calculateRedemptionFees(
            address(this),
            tco2s,
            amounts
        );
        feeDistributionTotal = getFeeDistributionTotal(feeDistribution);
    }

    /// @notice Deposit function for pool that accepts TCO2s and mints pool token 1:1
    /// @param tco2 TCO2 to be deposited. The pool contract needs to be approved in the
    /// TCO2 contract by the caller in order to allow the transfer of TCO2 tokens to the pool
    /// @param amount Amount of TCO2 to be deposited
    /// @param maxFee Maximum fee to be paid for the deposit. This value cannot be zero.
    /// Use `calculateDepositFees(tco2,amount)` to determine the fee that will be charged
    /// given the state of the pool during this call. Add a buffer on top of the returned
    /// fee amount up to the maximum fee you are willing to pay.
    /// @dev Eligibility of the ERC20 token to be deposited is checked via `checkEligible`
    /// @return mintedPoolTokenAmount Amount of pool tokens minted to the caller
    function deposit(
        address tco2,
        uint256 amount,
        uint256 maxFee
    ) external returns (uint256 mintedPoolTokenAmount) {
        if (address(feeCalculator) != address(0)) {
            require(maxFee != 0, Errors.CP_INVALID_MAX_FEE);
        }
        return super._deposit(_buildPoolVintageToken(tco2), amount, maxFee);
    }

    /// @notice Redeem TCO2s for pool tokens 1:1 minus fees
    /// The amounts provided are the exact amounts of TCO2s to be redeemed.
    /// @param tco2s Array of TCO2 contract addresses
    /// @param amounts Array of TCO2 amounts to redeem
    /// The indexes of this array are matching 1:1 with the tco2s array.
    /// @param maxFee Maximum fee to be paid for the redemption. This value cannot be zero.
    /// Use `calculateRedemptionOutFees(tco2s,amounts,false)` to determine the fee that will
    /// be charged given the state of the pool during this call. Add a buffer on top of the
    /// returned fee amount up to the maximum fee you are willing to pay.
    /// @return poolAmountSpent The amount of pool tokens spent by the caller
    function redeemOutMany(
        address[] memory tco2s,
        uint256[] memory amounts,
        uint256 maxFee
    ) external virtual returns (uint256 poolAmountSpent) {
        if (address(feeCalculator) != address(0)) {
            require(maxFee != 0, Errors.CP_INVALID_MAX_FEE);
        }
        require(tco2s.length == 1, Errors.CP_NOT_SUPPORTED);
        PoolVintageToken[] memory vintages = _buildPoolVintageTokens(tco2s);
        (, poolAmountSpent) = _redeemOutMany(vintages, amounts, maxFee, false);
    }
}

